def transform(grid):
    """Extend the central row and column of every solid 3x3 block."""
    h, w = len(grid), len(grid[0])
    rays = [[set() for _ in range(w)] for _ in range(h)]
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                cr, cc = r + 1, c + 1
                for x in range(w):
                    rays[cr][x].add(color)
                for y in range(h):
                    rays[y][cc].add(color)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if rays[r][c]:
                out[r][c] = next(iter(rays[r][c])) if len(rays[r][c]) == 1 else 0
    return out
